/* 静态站点：姓名、证据、反馈草稿均保存在本机；GitHub最终提交由学生完成。 */
(()=>{'use strict';
const M=window.CourseEvidence,$=s=>document.querySelector(s),KEY='orbit-competency-v1',PROFILE='orbit-student-profile-v1',DRAFT='orbit-feedback-draft-v1';
function read(key,fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback;}catch{return fallback;}}
let extra;try{extra=M.validateExtra(read(KEY,null));}catch{extra=M.validateExtra();}
let profile=read(PROFILE,{}),selectedDimension=0;
try{profile.name=M.cleanName(profile.name);}catch{profile={name:''};}
function store(key,value,status){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{if(status)status.textContent='本机保存失败。请复制记录或导出备份，暂时不要离开页面。';return false;}}
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function button(text,fn,cls='quiet'){const b=el('button',text,cls);b.type='button';b.onclick=fn;return b;}
function dialog(id,title){const d=el('dialog',undefined,'course-dialog');d.id=id;d.setAttribute('aria-label',title);const body=el('div',undefined,'course-form');body.append(el('h2',title));d.append(body);document.body.append(d);return [d,body];}
const [nameDialog,nameBody]=dialog('student-dialog','先认识一下你');
nameBody.append(el('p','填写自己的姓名，作为课堂里的用户名。学习记录保存在当前浏览器；提交公开反馈时才会带上姓名。'));
const nameLabel=el('label','你的姓名');nameLabel.htmlFor='student-name';const nameInput=el('input');nameInput.id='student-name';nameInput.maxLength=30;nameInput.autocomplete='name';const nameStatus=el('p','','form-status');nameStatus.setAttribute('role','status');
nameBody.append(nameLabel,nameInput,nameStatus);
const nameActions=el('div',undefined,'form-actions');nameActions.append(button('保存姓名，进入课堂',()=>{try{const next={name:M.cleanName(nameInput.value)};if(!store(PROFILE,next,nameStatus))return;profile=next;nameDialog.close();updateFrame();}catch(e){nameStatus.textContent=e.message;}},'primary'),button('关闭',()=>nameDialog.close()));nameBody.append(nameActions);
const ONBOARDING='orbit-onboarding-v1';let tourSuppressed=read(ONBOARDING,{})?.seen===true;
function maybeShowWelcome(){if(tourSuppressed||window.currentOrbitTask?.().tourDone||document.querySelector('dialog[open]'))return;window.showClassroomTour?.();}
$('#tour').addEventListener('close',()=>{tourSuppressed=true;store(ONBOARDING,{schema:1,seen:true});if(!profile.name)setTimeout(editName,0);});
nameDialog.addEventListener('close',()=>setTimeout(maybeShowWelcome,0));
function editName(){nameInput.value=profile.name;nameStatus.textContent='';if(!nameDialog.open)nameDialog.showModal();nameInput.focus();}
nameInput.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();nameActions.firstChild.click();}});

const names={0:'导读',1:'Git 时光机',2:'认识 Godot',3:'驾驭 AI',4:'拆解真游戏',5:'写一页设计',6:'做出原型',7:'发布与反馈'};
const stepNames=['领取任务','视频 / 资料学习','理解挑战','动手实践','总结领奖'];
function context(){const c=window.getCourseContext?.()||{station:0,phase:0};return {...c,label:c.station===null?'首页':('第'+c.station+'站 · '+names[c.station]+' / '+stepNames[c.phase||0])};}
function dimensionFor(station){return M.dimensions.find(d=>d.stations.includes(station));}
function evidenceData(){return M.evaluate(window.getStationRecords?.()||read('orbit-classroom-stations-v1',{}),window.currentOrbitTask?.()||read('orbit-classroom-godot-v1',{}),extra);}
function chart(data){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 380 330');svg.classList.add('evidence-chart');svg.setAttribute('role','img');svg.setAttribute('aria-label',data.map(d=>d.name+' '+(d.assessed?d.score+'分证据覆盖':'待评估')).join('，'));const xy=(i,f)=>[190+Math.sin(i*2*Math.PI/5)*104*f,159-Math.cos(i*2*Math.PI/5)*104*f];const shape=(tag,attrs)=>{const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);svg.append(n);return n;};
for(const f of [.2,.4,.6,.8,1])shape('polygon',{points:data.map((_,i)=>xy(i,f).join(',')).join(' '),fill:'none',stroke:'#444','stroke-width':1});for(let i=0;i<5;i++){const p=xy(i,1);shape('line',{x1:190,y1:159,x2:p[0],y2:p[1],stroke:'#333'});}shape('polygon',{points:data.map((d,i)=>xy(i,d.score/100).join(',')).join(' '),fill:'#ffffff18',stroke:'#ddd','stroke-width':1.5});data.forEach((d,i)=>{const p=xy(i,1.36);const t=shape('text',{x:p[0],y:p[1],'text-anchor':'middle'});t.textContent=d.name;const sub=shape('text',{x:p[0],y:p[1]+17,'text-anchor':'middle'});sub.textContent=d.assessed?d.score+' / 100':'待评估';});return svg;}
function renderRadar(){const root=$('#detail-radar');if(!root)return;const data=evidenceData();root.replaceChildren();const top=el('div',undefined,'evidence-top'),intro=el('div',undefined,'evidence-overview');intro.append(el('strong','看见已经检查的学习证据'),el('p','雷达五维对应课程内容。每维包含五个评价层级，每层占20分。分数表示已检查证据的覆盖程度，不是对你全部能力的判定。'),el('p','尚未检查的项目显示“待评估”。观看确认、任务积分、文字长度和自评均不会直接增加雷达分数。作品证据需教师另行确认。'));top.append(chart(data),intro);root.append(top);const tabs=el('div',undefined,'dimension-tabs');tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','能力维度');data.forEach((d,i)=>{const b=button(d.name,()=>{selectedDimension=i;renderRadar();tabs.focus();});b.setAttribute('role','tab');b.setAttribute('aria-selected',String(i===selectedDimension));b.id='dimension-tab-'+i;b.setAttribute('aria-controls','dimension-panel');tabs.append(b);});root.append(tabs);const dim=data[selectedDimension],rows=el('div',undefined,'evidence-levels');rows.id='dimension-panel';rows.setAttribute('role','tabpanel');rows.setAttribute('aria-labelledby','dimension-tab-'+selectedDimension);
dim.levels.forEach(l=>{const row=el('div',undefined,'evidence-row'),copy=el('div');copy.append(el('strong',l.status+' · '+l.passed+' / '+l.total+' 项'),el('p',l.evidence.join('；')||(['concept','reasoning'].includes(l.id)?'完成对应站点的理解挑战，按答案检查。':'需要真实作品、操作结果和验收证据；仅填写记录不会计为掌握。')));if(l.pending)copy.append(el('p',l.pending+' 份证据已保存在本机，待与老师核对。'));row.append(el('strong',l.name),copy,button(['concept','reasoning'].includes(l.id)?'去理解挑战 →':'查看实战任务 →',()=>{closeScores();window.openCourseStation?.(dim.stations[0],['concept','reasoning'].includes(l.id)?2:3);}));rows.append(row);});root.append(rows,el('p','说明：Godot信号实验仅验证网页模拟中的预测，不代表已在真实工程中掌握。当前静态版不提供教师在线评分后台。','evidence-caption'));
}
function closeScores(){$('#scores')?.close();}

// 实践题分别要求应用、独创、验证；每站均对应本地学习资料的方法。
const assignments={
1:{application:['在练习项目完成一次提交，核对 git log，并说明工作区、暂存区和提交各发生了什么。','提交哈希或终端记录；操作前后差异；三区域解释。'],creation:['为自己的项目设计一个安全存档方案：哪些改动前提交、提交信息怎样写、远程备份何时做。','真实项目场景；可执行的存档规则；选择理由。'],improvement:['制造一次可恢复的小改动，先预测恢复结果，再执行恢复；比较预期与实际并改进流程。','恢复前后记录；所用版本；不丢失重要改动的检查。']},
2:{application:['在自己的Godot工程用信号让两个节点通信，记录连接前后运行结果。','节点与场景位置；连接方式；运行结果。'],creation:['把信号方法用在一个自己的交互里，如开门或收集道具，并解释各节点职责。','自己的交互目标；场景结构；信号发送与接收职责。'],improvement:['故意断开或重复连接信号，预测异常并定位原因，修正后重新运行。','异常复现；原因证据；修复后的对照。']},
3:{application:['给AI一项小修改：写清目标、上下文、约束和验收，再检查它的改动。','实际工作单；修改差异；亲自运行的验收记录。'],creation:['针对自己项目设计一份可复用AI工作单，拆分一个新功能并说明拆分理由。','项目真实目标；独立制定的边界；可执行验收。'],improvement:['找出AI输出中一个未满足验收的点，补充证据后重新提出要求并比较结果。','原始失败；反馈依据；两版结果对照。']},
4:{application:['选择玩过的游戏，按动词、目标、反馈和循环拆解一次真实游玩片段。','具体游玩片段；行为与反馈证据；闭环描述。'],creation:['选一个不同题材游戏，独立提出一个可验证的体验假设。','自己的问题；样本依据；验证办法。'],improvement:['补玩或请同学测试，用观察反例修正最初的拆解结论。','原假设；反例记录；修订结论。']},
5:{application:['依据一页纸方法，把自己的游戏目标、核心循环、范围与验收写成一页设计。','完整的一页设计；可玩循环；范围边界。'],creation:['独立设计一个最小机制，用玩家动作和目标解释它为何成立。','新机制与选择理由；关键假设；最小验证范围。'],improvement:['请同学按设计解释玩法，记录理解偏差，修改设计并说明改动依据。','真实反馈；前后版本；调整理由。']},
6:{application:['把一页设计中的最小核心循环实现为可运行原型，并按验收逐项检查。','运行入口；操作方式；循环完成记录。'],creation:['独立做一个有明确范围的小功能，先写接口与验收，再实现。','自己的功能设计；可玩结果；范围控制。'],improvement:['记录一个能复现的缺陷，提出原因，修改并做回归检查。','复现步骤；修改位置；修复前后验证。']},
7:{application:['按资料导出自己的游戏，让另一台电脑实际打开并记录过程。','构建版本；打开方式；异机运行结果。'],creation:['为作品准备简明说明与展示页，让第一次接触的玩家知道怎样玩。','作品入口；面向新玩家的说明；自己的表达。'],improvement:['收集一次真实试玩反馈，选择一个问题修复，给出更新前后的对照。','试玩问题；取舍理由；新版本验证。']}
};
function practiceBlock(station){const section=el('section',undefined,'evidence-practice');section.dataset.evidencePractice=station;const dim=dimensionFor(station);section.append(el('span',dim.name+' / 进阶评价','evidence-caption'),el('h3','留下真正能被检查的成果'),el('p','按你的进度选择挑战。文字在本机保存，状态是“待教师确认”；请课堂展示或按老师约定交付作品。这里不会自动上传工程或增加能力分数。'));
for(const [level,label]of M.levels.slice(2)){const [prompt,rubric]=assignments[station][level],key=station+':'+level,details=el('details'),summary=el('summary',label+' · '+(extra.submissions[key]?'本机已留证':'待评估'));details.append(summary,el('p',prompt),el('p','核对依据：'+rubric));const input=el('textarea');input.maxLength=4000;input.value=extra.submissions[key]?.text||'';input.setAttribute('aria-label',names[station]+' '+label+'证据');input.placeholder='记录作品位置、实际操作与结果，或填写可查看的作品链接。';const status=el('p',extra.submissions[key]?'证据保存在本机，尚未交给老师。':'','evidence-caption');status.setAttribute('role','status');const save=button('保存为待确认的证据',()=>{if(input.value.trim().length<12){status.textContent='请至少写12个字，记录可核对的操作、作品位置与结果。';return;}const candidate={...extra,submissions:{...extra.submissions,[key]:{text:input.value.trim(),submittedAt:new Date().toISOString()}}};if(!store(KEY,candidate,status))return;extra=candidate;summary.textContent=label+' · 本机已留证';status.textContent='已保存在本机，待课堂向老师展示；雷达分数尚未改变。';renderRadar();});details.append(input,save,status);section.append(details);}return section;}
function decorate(){const c=context(),dim=dimensionFor(c.station);for(const id of ['#quest','#generic-class','#intro-dialog','#lesson-reader']){const d=$(id);if(!d||d.querySelector('.course-feedback'))continue;const close=d.querySelector('.dialog-head .close');if(close){const b=button('问题反馈 ↗',openFeedback,'course-utility course-feedback');close.before(b);}}
let container;if($('#generic-class')?.open)container=$('#generic-content');else if($('#quest')?.open)container=$('#quest [data-panel="'+c.phase+'"]');
if(container&&dim){let tag=container.querySelector('.evidence-tag');if(!tag){tag=el('p','','evidence-tag');container.prepend(tag);}tag.textContent=dim.name+' · '+(c.phase===2?M.levels.find(l=>l[0]===M.quizLevels[c.station][c.questionIndex||0])?.[1]:'本站任务积分与能力证据分别记录');if(c.phase===3&&!container.querySelector('[data-evidence-practice]'))container.append(practiceBlock(c.station));}
}

const [feedbackDialog,feedbackBody]=dialog('feedback-dialog','把遇到的问题告诉老师');
feedbackBody.append(el('p','先在这里整理问题，再前往 GitHub 提交。需要使用你自己的 GitHub 账号。'));
const feedbackWho=el('p'),changeName=button('修改姓名',editName);feedbackBody.append(feedbackWho,changeName);
const controls={};function field(id,label,tag='input'){const lab=el('label',label);lab.htmlFor=id;const input=el(tag);input.id=id;controls[id]=input;feedbackBody.append(lab,input);return input;}
const category=field('feedback-category','问题类型','select');M.categories.forEach(v=>{const o=el('option',v);o.value=v;category.append(o);});
const title=field('feedback-title','问题标题');title.maxLength=100;
const steps=field('feedback-steps','怎样操作后遇到问题？','textarea');steps.maxLength=1500;
const details=field('feedback-details','实际发生了什么？你希望出现什么？','textarea');details.maxLength=3000;
const feedbackLocation=el('p','','evidence-caption');feedbackBody.append(feedbackLocation,el('p','公开提醒：你的姓名、问题文字和附件会对所有人可见。请勿填写密码、令牌、联系方式或他人隐私。','public-note'));
const consent=el('input');consent.type='checkbox';consent.id='feedback-public';const consentLabel=el('label');consentLabel.append(consent,document.createTextNode('我知道姓名和问题会公开，愿意前往 GitHub 提交。'));feedbackBody.append(consentLabel);
const feedbackStatus=el('p','','form-status');feedbackStatus.setAttribute('role','status');feedbackBody.append(feedbackStatus);
let reportContext='首页';
function saveDraft(){const d={};for(const[id,input]of Object.entries(controls))d[id]=input.value;d.context=reportContext;return store(DRAFT,d,feedbackStatus);}
Object.values(controls).forEach(input=>input.addEventListener('input',()=>{if(saveDraft())feedbackStatus.textContent='草稿已保存在本机，尚未提交给老师。';}));
function report(){return {name:profile.name,title:title.value,category:category.value,steps:steps.value,details:details.value,context:reportContext};}
function openFeedback(){$('#feedback-direct-link')?.remove();const draft=read(DRAFT,{});reportContext=context().label;for(const[id,input]of Object.entries(controls))input.value=typeof draft[id]==='string'?draft[id]:input.tagName==='SELECT'?M.categories[0]:'';feedbackWho.textContent='提交姓名：'+(profile.name||'尚未填写');feedbackLocation.textContent='当前学习位置：'+reportContext;consent.checked=false;feedbackStatus.textContent='草稿仅存本机；打开填写页后还需在 GitHub 点击提交。';if(!feedbackDialog.open)feedbackDialog.showModal();}
const feedbackActions=el('div',undefined,'form-actions');feedbackActions.append(button('前往 GitHub 提交 ↗',()=>{try{if(!profile.name){editName();return;}if(!consent.checked){feedbackStatus.textContent='请先确认姓名和问题将公开。';return;}const url=M.issueUrl(report());saveDraft();const opened=window.open(url,'_blank');if(opened){opened.opener=null;feedbackStatus.textContent='已打开 GitHub 填写页。请登录并点击提交；此处不能确认老师已收到。';}else{feedbackStatus.textContent='浏览器可能阻止了新窗口。请使用下面的链接继续；尚未提交。';}let link=$('#feedback-direct-link');if(!link){link=el('a','打开预填的 GitHub Issue ↗');link.id='feedback-direct-link';link.target='_blank';link.rel='noopener noreferrer';feedbackBody.append(link);}link.href=url;if(new URL(url).searchParams.get('body').includes('请粘贴完整描述'))feedbackStatus.textContent+=' 内容较长，请先点“复制问题描述”，到 GitHub 粘贴完整正文后再提交。';}catch(e){feedbackStatus.textContent=e.message;}},'primary'),button('复制问题描述',async()=>{try{const url=new URL(M.issueUrl(report()));await navigator.clipboard.writeText(url.searchParams.get('title')+'\n\n'+M.issueBody(report()));feedbackStatus.textContent='已复制。请自行发送给老师；复制不会提交问题。';}catch(e){feedbackStatus.textContent='未能复制：'+e.message+'。可以直接选择并复制输入框里的文字。';}}),button('关闭',()=>feedbackDialog.close()));feedbackBody.append(feedbackActions);
feedbackDialog.addEventListener('close',()=>saveDraft());nameDialog.addEventListener('close',()=>{feedbackWho.textContent='提交姓名：'+(profile.name||'尚未填写');});

function updateFrame(){const d=$('#orbit-frame')?.contentDocument;if(!d?.querySelector('#start'))return;let controls=d.querySelector('#student-tools');if(!controls){d.querySelector('.nav a')?.remove();controls=d.createElement('div');controls.id='student-tools';controls.style.cssText='display:flex;gap:10px;align-items:center;flex-wrap:wrap';const name=d.createElement('button');name.id='student-profile';name.className='text-button';name.onclick=editName;const feedback=d.createElement('button');feedback.id='student-feedback';feedback.className='text-button';feedback.textContent='问题反馈 ↗';feedback.onclick=openFeedback;controls.append(name,feedback);d.querySelector('.header').append(controls);const style=d.createElement('style');style.textContent='.header{flex-wrap:wrap;gap:12px}.header .nav{flex-wrap:wrap;gap:18px}#student-tools button{font-size:12px}#student-tools{max-width:100%}@media(max-width:650px){.header{padding-top:16px;padding-bottom:16px}#student-tools{margin-left:auto}#student-tools button{font-size:11px}.header .nav{gap:10px}}';d.head.append(style);}d.querySelector('#student-profile').textContent=profile.name?'同学：'+profile.name:'填写姓名';d.querySelector('#student-profile').setAttribute('aria-label','修改学生姓名');}
function refreshPractice(){document.querySelectorAll('[data-evidence-practice]').forEach(e=>e.remove());decorate();}
window.CourseEvidenceUI={renderRadar,editName,openFeedback,decorate,exportState:()=>({assessment:extra,profile:{name:profile.name}}),validateBackup:value=>{if(value===undefined)return M.validateExtra();if(!value||typeof value!=='object')throw Error('附加存档格式错误');return M.validateExtra(value.assessment);},restoreBackup:value=>{const next=M.validateExtra(value?.assessment);if(!store(KEY,next))throw Error('能力记录保存失败');extra=next;refreshPractice();renderRadar();},reset:()=>{extra=M.validateExtra();store(KEY,extra);refreshPractice();renderRadar();}};
$('#orbit-frame')?.addEventListener('load',updateFrame);updateFrame();renderRadar();decorate();
const oldHome=window.updateIntroHome;window.updateIntroHome=(...args)=>{oldHome?.(...args);renderRadar();updateFrame();};
document.addEventListener('course:change',()=>{renderRadar();decorate();});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="scores"]'))setTimeout(renderRadar,0);if(e.target.closest('[data-action="reset-confirm"]'))setTimeout(()=>window.CourseEvidenceUI.reset(),0);setTimeout(decorate,0);});
setTimeout(()=>{if(!tourSuppressed&&!window.currentOrbitTask?.().tourDone)maybeShowWelcome();else if(!profile.name)editName();},120);
})();
